/**
 * @method
 * @name fn_open_report_year
 * @description desc
 * @param {string} dataSetCSV desc
 * @param {string} rex_rptname desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_open_report_year = function(dataSetCSV, rex_rptname) {
    scwin.fn_open_report(dataSetCSV, rex_rptname, null);
};


/****************************************************
 * 내부용 보고서 인쇄 - 가우스데이타셋 연동 - 멀티 데이타셋
 ****************************************************/
/**
 * @method
 * @name fn_open_report
 * @description desc
 * @param {string} dataSetCSV desc
 * @param {string} rex_rptname desc
 * @param {string} userParam desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_open_report = function(dataSetCSV, rex_rptname, userParam) {
    var oRptMainParam;
    oRptMainParam = rex_GetgoDictionay();

    // 필수 - 레포트명
    oRptMainParam.put("rex_rptname", rex_rptname);

    // 필수 - 데이터 타입 설정
    oRptMainParam.put("rex_datatype", "CSVSTR");
    oRptMainParam.put("rex_data", dataSetCSV);

    // 옵션 - 파라미터 정의
    if (userParam != null && userParam.length > 0) {
        for (i = 0; i < userParam.length; i++) {
            oRptMainParam.put(userParam[i].uid, userParam[i].unm);
        }
    }

    // 옵션 - 인쇄속성
    //oRptMainParam.put("rex_print", "direct=true;startpage=1;endpage=-1;count=1;skipzero=true");

    // 옵션 저장속성 
    //oRptMainParam.put("rex_save_file_type", "txt");
    //oRptMainParam.put("rex_save_file", "c:\Temp\aaa.txt");

    // 옵션 - 팝업설정
    var rex_gsPreViewFeaturesCustom = "center=yes,scrollbars=no,status=no,toolbar=no,resizable=1,location=no,menu=no,width=825,height=1000";
    oRptMainParam.put("rex_open_window", rex_gsPreViewFeaturesCustom);
    //var rex_gsPreViewFeaturesModalCustom = "center:yes;resizable__yes;scroll:yes;status:no;dialogWidth:825px;dialogHeight:1000px";
    //oRptMainParam.put("rex_open_window", rex_gsPreViewFeaturesModalCustom);

    // preview 팝업 열기
    rex_gfRexRptOpen("popup", oRptMainParam);
    //rex_gfRexRptOpen("popupmodal", oRptMainParam);

};



/****************************************************
 * 외부용 보고서 인쇄 -  단건 XML연동
 ****************************************************/
/**
 * @method
 * @name fn_PrintPreView
 * @description desc
 * @param {string} _rexName desc
 * @param {string} _dataType desc
 * @param {string} _dataLocation desc
 * @param {string} _dataXPath desc
 * @param {string} _svrGubun desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_PrintPreView = function(_rexName, _dataType, _dataLocation, _dataXPath, _svrGubun) {
    alert("_rexName=" + _rexName + ",_dataType=" + _dataType);
    alert("_dataLocation=" + _dataLocation + ", _dataXPath=" + _dataXPath + ",_svrGubun=" + _svrGubun);

    // 필수 - rexpert선언 
    var oRptMainParam = rex_GetgoDictionay();
    oRptMainParam.put("rex_rptname", _rexName);
    oRptMainParam.put("rex_datatype", _dataType);
    if ((_svrGubun == "dev") || (_svrGubun == "local")) {
        //개발&로컬
        oRptMainParam.put("rex_data", "https://idev-staff.krx.co.kr" + _dataLocation); //개발서버		  

    } else if (_svrGubun == "test") {
        //테스트
        oRptMainParam.put("rex_data", "https://itest-staff.krx.co.kr" + _dataLocation); //테스트 서버

    } else if (_svrGubun == "dr") {
        //DR
        oRptMainParam.put("rex_data", "https://dr-staff.krx.co.kr" + _dataLocation); //DR서버

    } else {
        //운영1,2 (반영)
        oRptMainParam.put("rex_data", "https://staff.krx.co.kr" + _dataLocation); //운영서버

    }
    oRptMainParam.put("rex_xpath", _dataXPath);

    // 옵션 - 파라미터 정의
    //	oRptMainParam.put("test_data", "사용자 정의 파라미터");

    // MarkAny(위변조방지) 옵션 (상장외부리포트 필수)
    /*
	    oRptMainParam.put("rex_markany", "true");
	    oRptMainParam.put("rex_markany_param", "dllname=MAePageSAFERRexpert.dll;datafilename=MaPrintInfoKrxRex.dat;enablecapture=0;enablespool=0;enableprinter=0;enableprinterInfo=0;printeroption=3;imagesaferoption=0");
	    oRptMainParam.put("rex_markany_cellwidth", "16"); //사이즈 조정
	    oRptMainParam.put("rex_markany_cellheight", "2"); //사이즈 조정 
	    oRptMainParam.put("rex_markany_path", "https://" + location.host + "/markany/jsp/MaFpsCommon.jsp");
	    oRptMainParam.put("rex_markany_setpagedata", "MaPrintInfoKrxRex.dat");
	    */

    // 옵션 - 팝업설정
    var rex_gsPreViewFeaturesModalCustom = "center:yes;resizable__no;scroll:no;status:no;dialogWidth:825px;dialogHeight:768px";
    oRptMainParam.put("rex_open_window", rex_gsPreViewFeaturesModalCustom);

    // preview 팝업 열기
    rex_gfRexRptOpen("popupmodal", oRptMainParam);
};


// form 으로부터 param 가져오기
/**
 * @method
 * @name fn_ExtractParam
 * @description desc
 * @param {string} _frm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ExtractParam = function(_frm) {
    var params = '';
    var frmEle;
    for (i = 0; i < _frm.elements.length; i++) {
        frmEle = _frm.elements[i];
        switch (frmEle.type) {
            case 'text':
            case 'hidden':
            case 'password':
            case 'textarea':
            case 'select-one':
                params += frmEle.name + '=' + encodeURIComponent(frmEle.getValue()) + '&';
                break;
            case 'radio':
                if (frmEle.checked) params += frmEle.name + '=' + encodeURIComponent(frmEle.getValue()) + '&';
                break;
            case 'checkbox':
                if (frmEle.checked) {
                    params += frmEle.name + '=' + encodeURIComponent(frmEle.getValue());
                    params += '&';
                }
                break;
        }
    }
    return params.substr(0, params.length - 1);
};


/****************************************************
 * 2018.03.29 다운로드 기능 개선
 * Rexpert Preview -> PDF
 ****************************************************/
/**
 * @method
 * @name fn_open_report_pdf
 * @description desc
 * @param {string} pdf_rptname desc
 * @param {string} userParam desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_open_report_pdf = function(pdf_rptname, userParam) {
    if (document.getElementById("pdfPreView")) {
        document.body.removeChild(document.getElementById("pdfPreView"));
    }
    var time = new Date().getTime();
    var winTitle = "PDF";
    $c.frame.path('/').OuterWindow.window.open("", "pdf_preViewPopup_" + time, "left=0,top=0,width=825,height=768,resizable=yes,scrollbars=no,location=no,status=no");
    var form = document.createElement("form");
    form.setAttribute("id", "pdfPreView");
    form.setAttribute("name", "pdfPreView");
    form.setAttribute("method", "POST");
    form.setAttribute("target", "pdf_preViewPopup_" + time);
    form.setAttribute("action", "/filePdfload.do?method=getPdfInfo");

    // 옵션 - 파라미터 정의
    if (userParam != null && userParam.length > 0) {
        for (i = 0; i < userParam.length; i++) {
            var hiddenField = document.createElement("input");
            hiddenField.setAttribute("type", "hidden");
            hiddenField.setAttribute("id", userParam[i].uid);
            hiddenField.setAttribute("name", userParam[i].uid);
            if (userParam[i].uid.indexOf("jsonData") != -1) {
                hiddenField.setAttribute("value", JSON.stringify(userParam[i].unm));
            } else {
                hiddenField.setAttribute("value", userParam[i].unm);
            }
            form.appendChild(hiddenField);
        }
        var hiddenField = document.createElement("input");
        hiddenField.setAttribute("type", "hidden");
        hiddenField.setAttribute("id", "pdf_rptname");
        hiddenField.setAttribute("name", "pdf_rptname");
        hiddenField.setAttribute("value", pdf_rptname);
        form.appendChild(hiddenField);
    }
    document.body.appendChild(form);
    form.submit();
};
/**
 * @method
 * @name fn_make_dtsToArrOut
 * @description desc
 * @param {string} userParam desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_make_dtsToArrOut = function(userParam, dtsObj) {
    var dtsObjHeaders = (dtsObj.DataHeader).split(","); /* 해당 객체의 Header 정보 추출*/
    var dtsHeaders;
    var dtsHeaderNm;
    var tmpObj;
    for (var k = 0; k < dtsObjHeaders.length; k++) {
        tmpObj = new Object();
        dtsHeaders = (dtsObjHeaders[k]).split(":"); /* Header 정보 */
        dtsHeaderNm = dtsHeaders[0]; /* 실제 Header명 */

        tmpObj.uid = dtsHeaderNm;
        tmpObj.unm = "&nbsp;";
        userParam.push(tmpObj);
    }
    return userParam;
};


/**
 * 함수명	: fn_make_dtsToArr1
 * 기능		: dtsObj 데이터를 Array 형태로 Convert 하여 userParam 배열에 추가 해 준다.
 *  
 * @param dtsReportObj
 * @returns
 */
/**
 * @method
 * @name fn_make_dtsToArr1_wdf
 * @description desc
 * @param {string} userParam desc
 * @param {string} dtsObj desc
 * @param {string} dataFormatObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_make_dtsToArr1_wdf = function(userParam, dtsObj, dataFormatObj) {
    if (dtsObj == null || dtsObj.getTotalRow() == 0) {
        return scwin.fn_make_dtsToArrOut(userParam, dtsObj);
    }
    var dtsObjHeaders = (dtsObj.DataHeader).split(","); /* 해당 객체의 Header 정보 추출*/
    var dtsHeaders;
    var dtsHeaderNm;
    var dtsHeaderType;
    var tmpObj;
    var dtsReportValue;
    for (var j = 1; j <= dtsObj.getTotalRow(); j++) {
        //다중은 안됨

        for (var k = 0; k < dtsObjHeaders.length; k++) {
            tmpObj = new Object();
            dtsHeaders = (dtsObjHeaders[k]).split(":"); /* Header 정보 */
            dtsHeaderNm = dtsHeaders[0]; /* 실제 Header명 */
            dtsHeaderType = dtsHeaders[1]; /* 실제 Header Data Type */


            dtsReportValue = scwin.fn_getDtsValue(dtsObj, j, dtsHeaderType, dtsHeaderNm);
            if (dataFormatObj != null && dataFormatObj.length > 0) {
                for (var m = 0; m < dataFormatObj.length; m++) {
                    dfObj = (dataFormatObj[m]).split(":");
                    dfHeaderNm = dfObj[0];
                    dfNm = dfObj[1];
                    if (dtsHeaderNm == dfHeaderNm) {
                        dtsReportValue = scwin.fn_dataFormatValue(dfNm, dtsReportValue);
                        break;
                    }
                }
            }
            tmpObj.uid = dtsHeaderNm;
            tmpObj.unm = dtsReportValue;
            userParam.push(tmpObj);
        }
    }
    return userParam;
};
/**
 * @method
 * @name fn_make_dtsToJsonOut
 * @description desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_make_dtsToJsonOut = function(dtsObj) {
    var rtnArray = new Array(); /* 껍데기 모양만 만들어 주자 */

    var tmpObj = new Object();
    var dtsObjHeaders = (dtsObj.DataHeader).split(","); /* 해당 객체의 Header 정보 추출*/
    var dtsHeaders;
    var dtsHeaderNm;
    for (var k = 0; k < dtsObjHeaders.length; k++) {
        dtsHeaders = (dtsObjHeaders[k]).split(":"); /* Header 정보 */
        dtsHeaderNm = dtsHeaders[0]; /* 실제 Header명 */

        tmpObj[dtsHeaderNm] = "&nbsp;";
    }
    rtnArray.push(tmpObj);
    return rtnArray;
};


/**
 * 함수명	: fn_make_dtsToJson1
 * 기능		: dtsReportObj 데이터를 JsonData 형태로 Convert 한다
 *  
 * @param dtsReportObj
 * @returns
 */
/**
 * @method
 * @name fn_make_dtsToJson1
 * @description desc
 * @param {string} dtsReportObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_make_dtsToJson1 = function(dtsReportObj) {
    var rtnArray = new Array();
    if (dtsReportObj == null || dtsReportObj.getTotalRow() == 0) {
        rtnArray = scwin.fn_make_dtsToJsonOut(dtsReportObj);
        return {
            arrayData: rtnArray
        };
    }
    var dtsObjHeaders = (dtsReportObj.DataHeader).split(","); /* 해당 객체의 Header 정보 추출*/
    var dtsHeaders;
    var dtsHeaderNm;
    var dtsHeaderType;
    var tmpObj;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            dtsHeaders = (dtsObjHeaders[k]).split(":"); /* Header 정보 */
            dtsHeaderNm = dtsHeaders[0]; /* 실제 Header명 */
            dtsHeaderType = dtsHeaders[1]; /* 실제 Header Data Type */

            //tmpObj[dtsHeaderNm] = dtsReportObj.NameString(j, dtsHeaderNm);
            tmpObj[dtsHeaderNm] = scwin.fn_getDtsValue(dtsReportObj, j, dtsHeaderType, dtsHeaderNm);
        }
        rtnArray.push(tmpObj);
    }
    return {
        arrayData: rtnArray
    };
};



/**
 * 함수명	: fn_make_dtsToJson1_wdf
 * 기능		: dtsReportObj 데이터를 포맷(dataFormatObj)에 맞춰 JsonData 형태로 Convert 한다.
 * 
 * @param dtsReportObj
 * @param dataFormatObj
 * @returns
 */
/**
 * @method
 * @name fn_make_dtsToJson1_wdf
 * @description desc
 * @param {string} dtsReportObj desc
 * @param {string} dataFormatObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_make_dtsToJson1_wdf = function(dtsReportObj, dataFormatObj) {
    var rtnArray = new Array();
    if (dtsReportObj == null || dtsReportObj.getTotalRow() == 0) {
        rtnArray = scwin.fn_make_dtsToJsonOut(dtsReportObj);
        return {
            arrayData: rtnArray
        };
    }
    var dtsObjHeaders = (dtsReportObj.DataHeader).split(","); /* 해당 객체의 Header 정보 추출*/
    var dtsHeaders;
    var dtsHeaderNm;
    var dtsHeaderType;
    var dfObj; //DataFormat Obj
    var dfHeaderNm; //DataFormat할 Header 명
    var dfNm; //DataFormat Type

    var tmpObj;
    var dtsReportValue;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            dtsHeaders = (dtsObjHeaders[k]).split(":"); /* Header 정보 */
            dtsHeaderNm = dtsHeaders[0]; /* 실제 Header명 */
            dtsHeaderType = dtsHeaders[1]; /* 실제 Header Data Type */

            //tmpObj[dtsHeaderNm] = dtsReportObj.NameString(j, dtsHeaderNm);
            dtsReportValue = scwin.fn_getDtsValue(dtsReportObj, j, dtsHeaderType, dtsHeaderNm);
            if (dataFormatObj != null && dataFormatObj.length > 0) {
                for (var m = 0; m < dataFormatObj.length; m++) {
                    dfObj = (dataFormatObj[m]).split(":");
                    dfHeaderNm = dfObj[0];
                    dfNm = dfObj[1];
                    if (dtsHeaderNm == dfHeaderNm) {
                        dtsReportValue = scwin.fn_dataFormatValue(dfNm, dtsReportValue);
                        break;
                    }
                }
            }
            tmpObj[dtsHeaderNm] = dtsReportValue;
        }
        rtnArray.push(tmpObj);
    }
    return {
        arrayData: rtnArray
    };
};



/**
 * 함수명	: fn_make_dtsToJson1_wdf_wsum
 * 기능		: dtsReportObj 데이터를 포맷(dataFormatObj)에 맞춰 JsonData 형태로 Convert 한다.
 * 			: dtsReportObj 데이터 중 합계(dataSumObj)를 해야 하는 객체가 있다면, userParam 배열에 담아준다.
 * @param dtsReportObj
 * @param dataFormatObj
 * @param dataSumObj
 * @param userParam
 * @returns {Array}
 */
/**
 * @method
 * @name fn_make_dtsToJson1_wdf_wsum
 * @description desc
 * @param {string} dtsReportObj desc
 * @param {string} dataFormatObj desc
 * @param {string} dataSumObj desc
 * @param {string} userParam desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_make_dtsToJson1_wdf_wsum = function(dtsReportObj, dataFormatObj, dataSumObj, userParam) {
    var rtnArray = new Array();
    var rtnJosnArr = new Array();
    if (dtsReportObj == null || dtsReportObj.getTotalRow() == 0) {
        rtnJosnArr = scwin.fn_make_dtsToJsonOut(dtsReportObj);
        rtnArray[0] = {
            arrayData: rtnJosnArr
        };
        rtnArray[1] = userParam;
        return rtnArray;
    }
    var dtsObjHeaders = (dtsReportObj.DataHeader).split(","); /* 해당 객체의 Header 정보 추출*/
    var dtsHeaders;
    var dtsHeaderNm;
    var dtsHeaderType;
    var dfObj; //DataFormat Obj
    var dfHeaderNm; //DataFormat할 Header 명
    var dfNm; //DataFormat Type

    var dSumObj;
    var dSumToNm;
    var dSumHeaderNm;
    var dSumFormatNm;
    var dSumRtnArr = new Array();
    var tmpObj;
    var dtsReportValue;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            dtsHeaders = (dtsObjHeaders[k]).split(":"); /* Header 정보 */
            dtsHeaderNm = dtsHeaders[0]; /* 실제 Header명 */
            dtsHeaderType = dtsHeaders[1]; /* 실제 Header Data Type */

            //tmpObj[dtsHeaderNm] = dtsReportObj.NameString(j, dtsHeaderNm);
            dtsReportValue = scwin.fn_getDtsValue(dtsReportObj, j, dtsHeaderType, dtsHeaderNm);
            if (dataSumObj != null && dataSumObj.length > 0) {
                for (var n = 0; n < dataSumObj.length; n++) {
                    dSumObj = (dataSumObj[n]).split(":");
                    dSumToNm = dSumObj[0];
                    dSumHeaderNm = dSumObj[1];
                    if (dtsHeaderNm == dSumHeaderNm) {
                        if (dSumRtnArr[dSumToNm] == null) {
                            dSumRtnArr[dSumToNm] = dtsReportValue;
                        } else {
                            dSumRtnArr[dSumToNm] = parseFloat(dSumRtnArr[dSumToNm]) + parseFloat(dtsReportValue);
                        }
                        break;
                    }
                }
            }
            if (dataFormatObj != null && dataFormatObj.length > 0) {
                for (var m = 0; m < dataFormatObj.length; m++) {
                    dfObj = (dataFormatObj[m]).split(":");
                    dfHeaderNm = dfObj[0];
                    dfNm = dfObj[1];
                    if (dtsHeaderNm == dfHeaderNm) {
                        dtsReportValue = scwin.fn_dataFormatValue(dfNm, dtsReportValue);
                        break;
                    }
                }
            }
            tmpObj[dtsHeaderNm] = dtsReportValue;
        }
        rtnJosnArr.push(tmpObj);
    }
    var dSumRtnVal;

    //ISU_TOTAMT_SUM 컬럼의 경우 전체 합산 후 소수점 4자리에서 반올림 처리하기 위해서 하드코딩 추가
    for (var key in dSumRtnArr) {
        dSumRtnVal = dSumRtnArr[key];
        if (key == "ISU_TOTAMT_SUM" || key == "FST_ISU_TOT_AMT_SUM" || key == "EXIST_ISU_TOT_AMT_SUM" ||
            key == "ADD_ISU_TOTAMT_SUM" || key == "ACC_ISU_TOTAMT_SUM") {
            dSumRtnVal = Math.round(dSumRtnVal / 100000) / 1000;
            dSumRtnArr[key] = dSumRtnVal;
        }
    }
    for (var key in dSumRtnArr) {
        dSumRtnVal = dSumRtnArr[key];
        for (var n = 0; n < dataSumObj.length; n++) {
            dSumObj = (dataSumObj[n]).split(":");
            dSumToNm = dSumObj[0];
            dSumHeaderNm = dSumObj[1];
            if (dSumObj.length == 3) {
                //Format이 있을 시만
                dSumFormatNm = dSumObj[2];
                if (key == dSumToNm) {
                    if (!$c.ut.isEmpty(dSumFormatNm) && dSumFormatNm != "") {
                        dSumRtnVal = scwin.fn_dataFormatValue(dSumFormatNm, dSumRtnVal);
                    }
                    break;
                }
            }
        }
        userParam.push({
            uid: key,
            unm: dSumRtnVal
        });
    }
    rtnArray[0] = {
        arrayData: rtnJosnArr
    };
    rtnArray[1] = userParam;
    return rtnArray;
};


/**
 * 함수명	: fn_make_dtsToJson2
 * 기능		: dtsObj 데이터의 Header 모양으로, dtsReportObj 데이터를 JsonData 형태로 Convert 한다
 * 
 * @param dtsObj
 * @param dtsReportObj
 * @returns
 */
/**
 * @method
 * @name fn_make_dtsToJson2
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} dtsReportObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_make_dtsToJson2 = function(dtsObj, dtsReportObj) {
    var rtnArray = new Array();
    if (dtsReportObj == null || dtsReportObj.getTotalRow() == 0) {
        rtnArray = scwin.fn_make_dtsToJsonOut(dtsObj);
        return {
            arrayData: rtnArray
        };
    }
    var dtsObjHeaders = (dtsObj.DataHeader).split(","); /* 해당 객체의 Header 정보 추출*/
    var dtsHeaders;
    var dtsHeaderNm;
    var dtsHeaderType;
    var tmpObj;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            dtsHeaders = (dtsObjHeaders[k]).split(":"); /* Header 정보 */
            dtsHeaderNm = dtsHeaders[0]; /* 실제 Header명 */
            dtsHeaderType = dtsHeaders[1]; /* 실제 Header Data Type */

            //tmpObj[dtsHeaderNm] = dtsReportObj.NameString(j, dtsHeaderNm);
            tmpObj[dtsHeaderNm] = scwin.fn_getDtsValue(dtsReportObj, j, dtsHeaderType, dtsHeaderNm);
        }
        rtnArray.push(tmpObj);
    }
    return {
        arrayData: rtnArray
    };
};



/**
 * 함수명	: fn_make_dtsToJson2_wdf
 * 기능		: dtsObj 데이터의 Header 모양으로, dtsReportObj 데이터를 포맷(dataFormatObj)에 맞춰 JsonData 형태로 Convert 한다
 * 
 * @param dtsObj
 * @param dtsReportObj
 * @param dataFormatObj
 * @returns
 */
/**
 * @method
 * @name fn_make_dtsToJson2_wdf
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} dtsReportObj desc
 * @param {string} dataFormatObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_make_dtsToJson2_wdf = function(dtsObj, dtsReportObj, dataFormatObj) {
    var rtnArray = new Array();
    if (dtsReportObj == null || dtsReportObj.getTotalRow() == 0) {
        rtnArray = scwin.fn_make_dtsToJsonOut(dtsObj);
        return {
            arrayData: rtnArray
        };
    }
    var dtsObjHeaders = (dtsObj.DataHeader).split(","); /* 해당 객체의 Header 정보 추출*/
    var dtsHeaders;
    var dtsHeaderNm;
    var dtsHeaderType;
    var dfObj; //DataFormat Obj
    var dfHeaderNm; //DataFormat할 Header 명
    var dfNm; //DataFormat Type

    var tmpObj;
    var dtsReportValue;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            dtsHeaders = (dtsObjHeaders[k]).split(":"); /* Header 정보 */
            dtsHeaderNm = dtsHeaders[0]; /* 실제 Header명 */
            dtsHeaderType = dtsHeaders[1]; /* 실제 Header Data Type */

            //dtsReportValue = dtsReportObj.NameString(j, dtsHeaderNm);
            dtsReportValue = scwin.fn_getDtsValue(dtsReportObj, j, dtsHeaderType, dtsHeaderNm);
            if (dataFormatObj != null && dataFormatObj.length > 0) {
                for (var m = 0; m < dataFormatObj.length; m++) {
                    dfObj = (dataFormatObj[m]).split(":");
                    dfHeaderNm = dfObj[0];
                    dfNm = dfObj[1];
                    if (dtsHeaderNm == dfHeaderNm) {
                        dtsReportValue = scwin.fn_dataFormatValue(dfNm, dtsReportValue);
                        break;
                    }
                }
            }
            tmpObj[dtsHeaderNm] = dtsReportValue;
        }
        rtnArray.push(tmpObj);
    }
    return {
        arrayData: rtnArray
    };
};



/**
 * 함수명	: fn_make_dtsToJson2_wdf
 * 기능		: dtsObj 데이터의 Header 모양으로, dtsReportObj 데이터를 포맷(dataFormatObj)에 맞춰 JsonData 형태로 Convert 한다.
 * 				- dtsObj 데이터의 Header 모양과 dtsReportObj 데이터의 Header 모양이 다름
 * 
 * @param dtsObj
 * @param dtsReportObj
 * @param dataFormatObj
 * @returns
 */
/**
 * @method
 * @name fn_make_dtsToJson3_wdf
 * @description desc
 * @param {string} dtsFormatObj desc
 * @param {string} dtsReportObj desc
 * @param {string} dataFormatObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_make_dtsToJson3_wdf = function(dtsFormatObj, dtsReportObj, dataFormatObj) {
    var rtnArray = new Array();

    /*
	    if(dtsReportObj == null || dtsReportObj.CountRow == 0){
	    	rtnArray = fn_make_dtsToJsonOut(dtsObj);
	    	return {arrayData: rtnArray};
	    }
	    */

    var dtsHeaders;
    var dtsRepHeaderNm;
    var dtsDataHeaderNm;
    var dtsDataHeaderType;
    var dfObj; //DataFormat Obj
    var dfHeaderNm; //DataFormat할 Header 명
    var dfNm; //DataFormat Type

    var tmpObj;
    var dtsReportValue;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsFormatObj.length; k++) {
            dtsHeaders = (dtsFormatObj[k]).split(":"); /* Header 정보 */
            dtsRepHeaderNm = dtsHeaders[0]; /* 실제 report에 쓰일 Header명 */
            dtsDataHeaderNm = dtsHeaders[1]; /* 실 dataSect의 Header명 */
            dtsDataHeaderType = dtsHeaders[2]; /* 실 dataSect의 Header Type */

            //dtsReportValue = dtsReportObj.NameString(j, dtsHeaderNm);
            dtsReportValue = scwin.fn_getDtsValue(dtsReportObj, j, dtsDataHeaderType, dtsDataHeaderNm);
            if (dataFormatObj != null && dataFormatObj.length > 0) {
                for (var m = 0; m < dataFormatObj.length; m++) {
                    dfObj = (dataFormatObj[m]).split(":");
                    dfHeaderNm = dfObj[0];
                    dfNm = dfObj[1];
                    if (dtsDataHeaderNm == dfHeaderNm) {
                        dtsReportValue = scwin.fn_dataFormatValue(dfNm, dtsReportValue);
                        break;
                    }
                }
            }
            tmpObj[dtsRepHeaderNm] = dtsReportValue;
        }
        rtnArray.push(tmpObj);
    }
    return {
        arrayData: rtnArray
    };
};



/**
 * 함수명	: fn_getDtsValue
 * 기능		: 해당 DataSet의 dataType에 따라 value를 꺼내온다
 * 
 * @param dtsObj
 * @param nrow
 * @param dataType
 * @param dtsHeaderNm
 * @returns
 */
/**
 * @method
 * @name fn_getDtsValue
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} nrow desc
 * @param {string} dataType desc
 * @param {string} dtsHeaderNm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getDtsValue = function(dtsObj, nrow, dataType, dtsHeaderNm) {
    var rtnVal;
    if (dataType.indexOf("STRING") != -1) {
        rtnVal = dtsObj.getCellData(nrow, dtsHeaderNm);
        if (rtnVal.indexOf("\n") != -1) {
            rtnVal = $c.ut.replaceAll(rtnVal, "\n", "<br/>");
        }
    } else if (dataType.indexOf("BIGINT") != -1) {
        rtnVal = dtsObj.getCellData(nrow, dtsHeaderNm);
    } else if (dataType.indexOf("DECIMAL") != -1) {
        rtnVal = dtsObj.getCellData(nrow, dtsHeaderNm);
    } else {
        rtnVal = dtsObj.getCellData(nrow, dtsHeaderNm);
    }
    return rtnVal;
};



/**
 * 함수명	: fn_dataFormatValue
 * 기능		: 해당 DataSet의 datavalue를 원하는 포맷으로 꺼내온다
 * 
 * @param dataFormatType
 * @param dataValue
 * @returns
 */
/**
 * @method
 * @name fn_dataFormatValue
 * @description desc
 * @param {string} dataFormatType desc
 * @param {string} dataValue desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_dataFormatValue = function(dataFormatType, dataValue) {
    var rtnVal;
    switch (dataFormatType) {
        case "FormatNumberEx":
            /*				if(typeof dataValue === "number"){
	            					dataValue = dataValue.toString();
	            				}*/

            rtnVal = $c.stf.FormatNumberEx(dataValue);
            break;
        case "FormatTofixed3":
            if ($c.ut.isEmpty(dataValue) == true || dataValue == "" || dataValue == "undefined") {
                dataValue = 0;
            }
            rtnVal = $c.ut.FormatTofixed(dataValue, 3);
            break;
        case "FormatDateEx":
            rtnVal = $c.stf.FormatDateEx(dataValue); //YYYY-MM-DD
            break;
        case "FormatDateEx2":
            rtnVal = $c.stf.FormatDateEx2(dataValue); //YYYY.MM.DD
            break;
        case "FormatDateEx3":
            rtnVal = $c.stf.FormatDateEx3(dataValue); //YYYY년 MM월 DD일
            break;
        case "FormatDateEngEx1":
            rtnVal = $c.stf.FormatDateEngEx1(dataValue); //YYYYMMDD --> YYYY. MM. DD
            break;
        case "FormatDateEngEx2":
            rtnVal = $c.stf.FormatDateEngEx2(dataValue); //YYYYMMDD --> DD.MM.YYYY
            break;
        case "FormatDateEngEx3":
            rtnVal = $c.stf.FormatDateEngEx3(dataValue); //MMDDYYYY --> MM.DD.YYYY
            break;
        case "FormatDateExYYMM":
            rtnVal = $c.stf.FormatDateExYYMM(dataValue);
            break;
        case "":
            break;
    }
    return rtnVal;
};
